import {create,move,preview,advance,policy,configure,REQUESTS} from './engine.js?v=0.18.0';
import {validateCapacity} from './capacity.js?v=0.18.0';
export const KEY='thinking-lab:exceptions:v1';
const clone=structuredClone;
export function validateRun(raw){if(!raw||!Number.isInteger(raw.quarter)||raw.quarter<0||raw.quarter>6||!Array.isArray(raw.history)||raw.history.length!==raw.quarter)throw Error('Invalid run history.');let s=configure(create(),{aging:raw.aging,pairCost:raw.pairCost});if(raw.capacity)s.capacity=clone(validateCapacity(raw.capacity));
 for(let q=0;q<raw.quarter;q++){const h=raw.history[q];if(h.quarter!==q||!Array.isArray(h.decisions)||h.decisions.length!==s.entries.length||new Set(h.decisions.map(x=>x.id)).size!==h.decisions.length)throw Error('Invalid settled decisions.');for(const d of h.decisions){const found=s.entries.find(e=>e.id===d.id);if(!found)throw Error('Unknown settled request.');if(found.status==='retired'){if(d.plan!=='retired')throw Error('A retired request cannot reopen.');}else s=move(s,d.id,d.plan);}s=advance(s);if(!Number.isFinite(h.net)||Math.abs(s.history[q].net-h.net)>1e-7)throw Error('Settled value does not match its decisions.');}
 if(!Array.isArray(raw.entries)||raw.entries.length!==s.entries.length||new Set(raw.entries.map(e=>e.id)).size!==raw.entries.length)throw Error('Invalid current requests.');for(const e of raw.entries){const found=s.entries.find(x=>x.id===e.id);if(!found||e.status!==found.status||e.since!==found.since)throw Error('Current requests do not match the run history.');if(s.quarter===6||found.status==='retired'){if(e.plan!==found.plan)throw Error('Settled plans cannot change.');}else s=move(s,e.id,e.plan);}if(!Number.isFinite(raw.value)||Math.abs(raw.value-s.value)>1e-7)throw Error('Accumulated value does not match its history.');return s;}
export function comparePolicy(s,kind){let run={...create(),aging:s.aging,pairCost:s.pairCost,...(s.capacity?{capacity:clone(s.capacity)}:{})};while(run.quarter<6){const planned=policy(run,kind),p=preview(planned);if(p.capacity&&!p.capacity.feasible)return {id:kind,name:kind==='tailor'?'Keep requests tailored':'Standardise longer-lived requests',complete:false,quarter:run.quarter,required:p.capacity.required,budget:p.capacity.budget};run=advance(planned);}return {id:kind,name:kind==='tailor'?'Keep requests tailored':'Standardise longer-lived requests',complete:true,value:run.value,coreDone:run.history.reduce((n,h)=>n+(h.capacity?.coreDone||0),0),coreRemaining:run.history.at(-1).capacity?.coreRemaining??null,history:run.history};}
export function validateBundle(raw){const s=validateRun(raw?.s);const decision=raw.decision??'';if(typeof decision!=='string'||decision.length>20000)throw Error('Decision note is too long.');const comparisons=s.quarter===6&&Array.isArray(raw.comparisons)?[...new Set(raw.comparisons.map(c=>c.id))].map(id=>comparePolicy(s,id)):[];return {s,comparisons,decision};}
export function portable(b){return JSON.stringify({kind:'exceptions',version:2,...validateBundle(b)},null,2);}
export function parse(text){const raw=JSON.parse(text);if(raw.kind!=='exceptions'||raw.version!==2)throw Error('Choose an exported Exceptions experiment.');return validateBundle(raw);}
export function markdown(b){const {s,comparisons,decision}=validateBundle(b);return `# How exceptions accumulate\n\n${s.quarter}/6 quarters settled. Accumulated fictional value: ${s.value.toFixed(1)} points. ${s.capacity?'Effort-days and value points are separate assumptions.':'Earlier value-only run; no capacity model applied.'}\n\n${s.history.map(h=>`- Q${h.quarter+1}: net ${h.net.toFixed(1)} points.${h.capacity?` Budget ${h.capacity.budget.toFixed(1)} days; upkeep ${h.capacity.maintenance.toFixed(1)}; changes and exit ${(h.capacity.setup+h.capacity.retirement).toFixed(1)}; core work ${h.capacity.coreDone.toFixed(1)}; waiting ${h.capacity.coreRemaining.toFixed(1)}.`:''}`).join('\n')}\n\nDecision / next question: ${decision||'Not recorded.'}\n\nFictional whole-quarter choices; no partial implementations or operational failure model. Core work is divisible and serves arrival order. No uncalibrated conversion from value points to days.\n\n\`\`\`json\n${portable({s,comparisons,decision})}\n\`\`\`\n`;}
export function editEffort(s,id,key,value){if(!s.capacity||s.quarter>=6||!s.entries.some(e=>e.id===id&&e.status==='pending')||!['setup','standard','maintenance','retire'].includes(key))throw Error('Effort estimates are editable only before that request’s first settlement.');const next=clone(s);next.capacity.effort[id][key]=value;validateCapacity(next.capacity);return next;}
